using System;
using System.Collections.Generic;

namespace murumsWiiModStudio
{
    internal sealed class HelpTopic
    {
        public string Title, Summary, Route, Note, WorkspaceKey;
        public string[] Steps;
        public string[] VisualSteps;
        public StudioIcon[] StepIcons;
        public StudioIcon Icon;
        public string Group, VisualNote;
        public bool IncludeLinks;
        public bool ChecksUpdates;
        public string ExampleTitle, ExampleResult;
        public string[] ExampleSteps, ExampleHeadings;
        public StudioIcon[] ExampleIcons;
        public HelpPicture[] Pictures = new HelpPicture[0];
        public override string ToString()
        {
            return Title;
        }
    }

    internal sealed class HelpPicture
    {
        public string File, Caption;
        internal HelpPicture(string file, string de, string en)
        {
            File = "Help/" + (L.IsGerman ? "de-" : "en-") + file + ".png";
            Caption = L.T(de, en);
        }
    }

    internal static class StudioHelpTopics
    {
        static HelpTopic T(string de, string en, string sd, string se, string route, string[] d, string[] e, string nd, string ne)
        {
            return new HelpTopic
            {
                Title = L.T(de, en),
                Summary = L.T(sd, se),
                Route = route,
                Steps = L.IsGerman ? d : e,
                Note = L.T(nd, ne)
            };
        }

        public static List<HelpTopic> All()
        {
            var topics = new List<HelpTopic>
            {
                T("RR-Effektfarben", "RR effect colours", "Driftstufen, Stern-Partikel und Boost-Farben.", "Drift stages, star particles and boost colours.", "Tools > RR-MKWii Race Effects Tool",
                    new[] { "Quellen laden|Common.szs und CommonAssets.szs aus deinem RR-Pack hinzufügen.", "Effekte wählen|Kategorie wählen und gewünschte Effekte anhaken. Auswahl bleibt beim Kategorienwechsel erhalten.", "Farben testen|Haupt-/Nebenfarbe wählen, anwenden und separate Kopien speichern. In einem Offline-Rennen prüfen." },
                    new[] { "Load sources|Add Common.szs and CommonAssets.szs from your RR pack.", "Choose effects|Select a category and check the effects. Checks survive category changes.", "Test colours|Choose primary/secondary colours, apply and save separate copies. Check in an offline race." },
                    "Farbbeispiel ist schematisch. Originale Alpha-/Bewegungsspuren bleiben erhalten; Streckeneffekte können Farben übersteuern.",
                    "The colour sample is schematic. Original alpha/motion tracks are kept; course effects may override colours."),
                T("Pack-Werkstatt", "Pack Workshop", "Prüfen, Projektstand sichern und getrennt testen.", "Check, save snapshots and test separately.", "Tools > RR-MKWii Pack Workshop Tool",
                    new[] { "Pack prüfen|Den Pack-Ordner öffnen und prüfen. Die Prüfung umfasst BRLAN-Animationswerte und fehlende Ressourcenziele. Meldungen nennen betroffene Dateien; den ausgewählten Hinweis unterhalb der Tabelle lesen. Externe Referenzen sind Hinweise. Das ist keine vollständige BRSTM-Prüfung.", "Stand sichern|Einen neuen Ordner außerhalb der Quelle wählen. Wiederherstellen prüft alle Hashes und erzeugt eine neue Kopie.", "RR-Test starten|RR.json und eigene MKWii-ISO wählen, Testkopie erstellen, dann Dolphin.exe auswählen. Eigene Test-Spielstände." },
                    new[] { "Check the pack|Open a pack folder and check it. Checks include BRLAN animation values and missing resource targets. Findings identify files; read the selected detail below the table. External references are warnings. This is not a complete BRSTM validation.", "Save a snapshot|Choose a new folder outside the source. Restore validates hashes and creates a new copy.", "Launch an RR test|Choose RR.json and your MKWii ISO, create the test copy, then choose Dolphin.exe. Test saves are separate." },
                    "Prüfbericht und erfolgreicher Spielstart ersetzen keinen Test aller bearbeiteten Szenen.",
                    "A check report and successful boot do not replace testing every edited scene."),
                T("Änderungen kombinieren", "Combine edits", "Mehrere Kopien desselben Archivs sicher kombinieren.", "Safely combine copies of the same archive.", "Tools > RR-MKWii Mod Merge Tool",
                    new[] { "Original öffnen|Das unveränderte gemeinsame Ausgangsarchiv wählen.", "Bearbeitungen hinzufügen|Mehrere gleichnamige Kopien hinzufügen. Unabhängige Ressourcen werden kombiniert.", "Konflikte entscheiden|Bei derselben Ressource eine Version oder das Original wählen. Anschließend eine neue Kopie speichern." },
                    new[] { "Open the original|Choose the unchanged archive used as the shared starting point.", "Add edits|Add several copies with the same filename. Independent resources are combined.", "Resolve conflicts|Choose one version or the original for a conflicting resource, then save a new copy." },
                    "Es werden ganze Ressourcen kombiniert. Keine automatische Zusammenführung einzelner Layoutfelder.",
                    "Whole resources are combined. Individual layout fields are not merged automatically."),
                T("Schnellstart", "Quick start", "In vier Schritten vom Original zur getesteten Kopie.", "Four steps from the original to a tested copy.", L.T("Öffnen  →  Bearbeiten  →  Vorschau  →  Kopie", "Open  →  Edit  →  Preview  →  Copy"), new[] { "Quelle sichern|Lege eine Sicherung deines Custom Packs an.", "Tool wählen|Wähle links die passende Arbeitsfläche und lade deine Quelldateien. Ein gültiges Pack allein lädt noch keine Quelle.", "Änderung prüfen|Nutze die Vorschau. Übernimm nur die gewünschten Änderungen.", "Kopie testen|Speichere separat, übernimm sie in dein Testing-Pack und starte das Spiel neu." }, new[] { "Back up the source|Keep a backup of your custom pack.", "Choose a tool|Choose the appropriate workspace on the left and load your source files. A valid pack alone does not load a source.", "Review the change|Use its preview and apply only the changes you want.", "Test the copy|Save separately, install in your testing pack and restart the game." }, "Eine Vorschau bestätigt nicht automatisch die Darstellung im Spiel.", "A preview does not automatically confirm the in-game appearance."),
                T("Menühintergründe", "Menu backgrounds", "Bilder oder GIFs für die Menüs deines Packs.", "Pictures or GIFs for your pack's menus.", "Tools > RR-MKWii Backgrounds Tool", new[] { "Pack auswählen|Unter Ordner & Qualität deinen Custom-Pack-Ordner wählen.", "Bild zuordnen|Titel / Lizenz, Singleplayer oder Multiplayer wählen; Bild oder GIF laden und Vorschau prüfen.", "Kopien erstellen|Den Builder unten verwenden. Ergebnisse aus MUR_EDITED nach Sicherung ins Pack übernehmen." }, new[] { "Select the pack|Choose your custom pack in Folders & quality.", "Assign artwork|Choose Title / License, Single Player or Multiplayer. Load artwork and inspect the preview.", "Build copies|Use the bottom build button. Back up pack files before installing results from MUR_EDITED." }, "Spracharchive nur verwenden, wenn dein Pack sie enthält.", "Use language archives only when your pack contains them."),
                T("Globus, Himmel & Modelle", "Globe, sky & models", "Farben, Hintergrundbild und sichtbare Modelle einstellen.", "Set colours, background artwork and model visibility.", L.T("RR-MKWii Backgrounds Tool > Weitere UI", "RR-MKWii Backgrounds Tool > Other UI"), new[] { "Bereich wählen|Globus & Himmel oder 3D-Modelle öffnen.", "Darstellung einstellen|Farben wählen, Foto/GIF laden oder Modelle per Häkchen sichtbar lassen. Sternmuster werden gekachelt.", "Vorschau & Kopie|Zuschnitt und schematische Auswahl prüfen; anschließend unten erstellen." }, new[] { "Choose a section|Open Globe & sky or 3D models.", "Set appearance|Choose colours or a photo/GIF. Checked models remain visible. Star patterns tile.", "Preview and build|Review fitting and the schematic setup, then build at the bottom." }, "Die Globus-Farbvorschau zeigt eine schematische Kugel; die Modellvorschau zeigt geladene Archivmodelle. Beides ersetzt keinen Spieltest. Gemeinsame Modelle können mehrere Menüs verändern.", "The globe colour preview shows a schematic sphere; model preview shows loaded archive models. Neither replaces an in-game test. Shared models may affect several menus."),
                T("Race HUD: Bilder & Zahlen", "Race HUD: pictures & numbers", "Platzierung, Zeit, Runden, Score und weitere HUD-Bilder.", "Placement, time, laps, score and other HUD artwork.", "Tools > RR-MKWii Race HUD Tool", new[] { "Archive laden|Race.szs und die tatsächlich verwendete Sprachdatei laden. Font.szs und ReplacedAssets.szs bei Zahlen-/Slash-Änderungen mit berücksichtigen; zusätzliche RR-Ressourcen liegen in RaceAssets.szs.", "Element bearbeiten|Kategorie wählen. Bild ersetzen oder Colours nutzen. Number font erzeugt Zahlen aus einer TTF; Umfang und Vorschau prüfen.", "Änderungen speichern|Pending replacements prüfen. Save edited archives unten schreibt Kopien in MUR_EDITED." }, new[] { "Load archives|Load Race.szs and the language archive your game uses. Include Font.szs and ReplacedAssets.szs for digit/slash changes; extra RR resources are in RaceAssets.szs.", "Edit an element|Choose a category. Replace artwork or use Colours. Number font generates TTF digits; review scope and preview.", "Save changes|Review Pending replacements. Save edited archives at the bottom writes copies to MUR_EDITED." }, "Allgemeine Textschriften und HUD-Zahlen haben getrennte Quellen und Exportrollen. Die Schrift-Arbeitsfläche bietet ebenfalls koordinierte Zahlenänderungen. Spielmaterialien können Farben verändern.", "General text fonts and HUD digits have separate source and export roles. The Fonts workspace also offers coordinated digit changes. Game materials may change colours."),
                T("Minimap-Farben", "Minimap colours", "Grundfarbe, Transparenz und Farbverlauf der Karte.", "Map base colour, transparency and corner gradient.", L.T("RR-MKWii Race HUD > Kartenfarben", "RR-MKWii Race HUD > Map colours"), new[] { "Map-Layout wählen|Race.szs laden und Map colours öffnen.", "Farben einstellen|Map base oder eine Ecke wählen. Choose colour und Opacity ändern; Uniform colour setzt einen einheitlichen Verlauf.", "Übernehmen|Apply map changes klicken, dann im Race HUD unten speichern. Rückgängig über Pending replacements." }, new[] { "Choose the map layout|Load Race.szs and open Map colours.", "Set colours|Select Map base or a corner. Adjust Choose colour and Opacity; Uniform colour resets the gradient.", "Apply|Click Apply map changes, then save at the bottom of Race HUD. Undo via Pending replacements." }, "Die Musterstrecke ist eine Illustration, nicht die Geometrie deiner Strecke.", "The sample track is illustrative, not your course geometry."),
                T("Input Viewer", "Input Viewer", "Tasten, Steuerkreuz und Stick getrennt gestalten.", "Style buttons, D-pad and stick separately.", "RR-MKWii Race HUD > Input viewer", new[] { "Ressourcen laden|RaceAssets.szs direkt öffnen oder mit Add archive hinzufügen.", "Zustand wählen|On/Off-Dateien sind getrennte gedrückte und losgelassene Zustände. Bild ersetzen oder Colours wählen.", "Gemeinsam prüfen|Preview category zeigt die aktuellen Texturen. Danach Änderungen unten speichern." }, new[] { "Load resources|Open RaceAssets.szs directly or use Add archive.", "Choose a state|On/off files are separate pressed and released states. Replace the picture or choose Colours.", "Review together|Preview category shows current textures. Save changes at the bottom." }, "Die Übersicht zeigt Texturen, keine live reagierende Controller-Anzeige.", "The overview shows textures, not a live controller display."),
                T("Schriften ändern", "Change fonts", "Allgemeine Spielschriften mit einer TTF ersetzen.", "Replace general game fonts using a TTF.", "Tools > RR-MKWii Font Changer Tool", new[] { "Schrift auswählen|Font.szs öffnen, darin eine Textschrift wählen und eine System- oder Dateischrift laden.", "Stil prüfen|Füllung, Kontur und Hinting einstellen. Textprobe und Fontatlas prüfen; bei weiteren Schriftsystemen passende Schriften zuweisen. Zeichen prüfen… zeigt ersetzte, fehlende und geschützte Zeichen; Symbole… öffnet die separate Symbolprüfung. Archivübersicht… nennt geladene und fehlende Quellen. Mit Textfelder prüfen… Beispieltext in den geladenen Textfeldern auf Überbreite prüfen.", "Kopie speichern|Weitere Schriften bei Bedarf einzeln bearbeiten. Layoutbegleiter für echte Layoutvorschauen laden; bei HUD-Zahlen auch Race.szs/ReplacedAssets.szs berücksichtigen. Die angezeigten bearbeiteten Kopien gemeinsam exportieren." }, new[] { "Choose a font|Open Font.szs, select a text font inside it and load a system or file font.", "Review styling|Set fill, outline and hinting. Review the sample text and font atlas; assign suitable fonts for additional writing systems. Character check… shows replaced, missing and protected characters; Symbols… opens the separate symbol review. Archive overview… lists loaded and missing sources. Use Check text fields… to inspect sample text for overflow in the loaded text fields.", "Save a copy|Edit other fonts individually as needed. Load companion archives for real layout previews; include Race.szs/ReplacedAssets.szs for HUD digits. Export the displayed edited copies together." }, "Fehlende TTF-Zeichen behalten ihr Original. Graustufenformate können keine beliebigen Farben speichern.", "Missing TTF characters keep their originals. Grayscale formats cannot store arbitrary colours."),
                T("Menütexte", "Menu texts", "Nachrichten finden, bearbeiten und lesbar prüfen.", "Find, edit and preview messages.", "Tools > RR-MKWii Menu Text Tool", new[] { "Texte öffnen|Spracharchiv oder BMG öffnen und Ressource wählen.", "Nachricht ändern|Nach ID oder Text suchen, Textspalte bearbeiten. Die Vorschau zeigt Zeilenumbrüche.", "Kopie speichern|Save edited copy schreibt die Änderungen separat. Länge anschließend im Spiel prüfen." }, new[] { "Open messages|Open a language archive or BMG and choose its resource.", "Edit a message|Search by ID or text and edit the text column. The preview shows line breaks.", "Save a copy|Save edited copy writes changes separately. Check text length in game." }, "Steuerzeichen für Farben, Symbole und Variablen erhalten. Die Vorschau nutzt eine Systemschrift.", "Preserve colour, symbol and variable escapes. The preview uses a system font."),
                T("Musik & Loops", "Music & loops", "Loopbereich sehen und den Übergang anhören.", "See the loop range and listen to its seam.", "Tools > MKWii Music & Loops Tool", new[] { "Audio laden|PCM WAV öffnen oder andere Formate mit FFmpeg konvertieren.", "Loop setzen|Samples oder Sekunden als Loop-Einheit wählen. Sekunden werden auf das nächste Sample gerundet, halbe Samples aufwärts; der Einheitenwechsel erhält die Sampleposition. Das Ende ist exklusiv. Die Wellenform markiert den Bereich; Loop anhören spielt ihn wiederholt.", "Messwerte und Grenzen prüfen|Pegel und Vollaussteuerung werden je Kanal angezeigt; der Loop-Sprung vergleicht letztes und erstes Sample. Nahe Nulldurchgänge suchen prüft ±5 ms und ändert beide Marken gemeinsam nur bei verbesserter Nahtmetrik. Stereo behält einen gemeinsamen Sampleindex. Rückgängig nimmt beide Änderungen in einem Schritt zurück. Anschließend Loop anhören.", "Exportieren|WAV mit Loop speichern… verwenden. Im BRSTM-Konverter die Loopmarkierungen behalten." }, new[] { "Load audio|Open PCM WAV or convert other formats with FFmpeg.", "Set the loop|Choose Samples or Seconds as the loop unit. Seconds round to the nearest sample, halves upwards; switching units retains the sample position. The end is exclusive. The waveform marks the range; Preview loop repeats it.", "Review measurements and boundaries|Levels and full-scale counts are shown per channel; loop jump compares the last and first samples. Find nearby zero crossings checks ±5 ms and changes both markers together only when the seam metric improves. Stereo retains one shared sample index. Undo restores both markers in one step. Then use Preview loop.", "Export|Use Save looped WAV…. Keep loop markers when converting to BRSTM." }, "Samplepegel sind keine True-Peak- oder Lautheitsmessung. Vollaussteuerung beweist keine Verzerrung; kleiner Loop-Sprung und Nulldurchgangshilfe garantieren keinen hörbar sauberen Loop. BRSTM wird extern umgewandelt. Musik für die letzte Runde kann eine separate Datei benötigen.", "Sample levels are not true peak or loudness. Full scale does not prove distortion; a small loop jump and zero-crossing assistance do not guarantee an audibly clean loop. BRSTM conversion is external. Final-lap music may need a separate file."),
                T("Theme-Projekte", "Theme projects", "Fertige Änderungen zu einem Pack zusammenstellen.", "Collect finished edits into one output pack.", "Tools > RR-MKWii Theme Project Tool", new[] { "Projekt anlegen|Custom-Pack-Ordner als Basis wählen.", "Dateien zuordnen|Add edited file: erst Originalziel im Pack, dann Ersatzdatei wählen. Preview selected file prüfen.", "Speichern & bauen|Projekt als .mtheme speichern; Build theme folder erstellt die Ausgabe." }, new[] { "Create a project|Choose the custom pack as the base.", "Map files|Add edited file: choose the original target, then the replacement. Inspect Preview selected file.", "Save and build|Save the .mtheme project; Build theme folder creates the output." }, "Dateien bleiben verknüpft. Das Projekt speichert nicht automatisch die Einstellungen aller Editoren.", "Files remain linked. Projects do not automatically capture every editor's settings."),
                T("Archive vergleichen", "Compare archives", "Gewünschte Änderungen gezielt übernehmen.", "Select which changed resources to keep.", "Tools > MKWii Archive Compare Tool", new[] { "Versionen laden|Original öffnen… lädt den Ausgangsstand. Bearbeitung öffnen… lädt eine separate Kopie mit genau demselben Archivdateinamen.", "Unterschiede prüfen|Vergleich aktualisieren wählen. Eine Ressource anklicken, um beide Versionen und erkannte BRLYT-, BRLAN- oder TPL-Wertänderungen zu prüfen. Weitere Binäränderungen sind möglich; Details können begrenzt sein.", "Bericht oder Kopie speichern|Vergleichsbericht speichern… schreibt alle Pfade, Größen und begrenzte Details als TXT, unabhängig von den Häkchen. Für eine Spielarchivkopie nur gewünschte Ressourcen anhaken und Auswahl als Kopie speichern… verwenden." }, new[] { "Load versions|Open original… loads the base state. Open edited… loads a separate copy with exactly the same archive filename.", "Review differences|Choose Refresh comparison. Select a resource to inspect both versions and recognised BRLYT, BRLAN or TPL value changes. Other binary changes are possible; details may be limited.", "Save a report or copy|Save comparison report… writes all paths, sizes and bounded details as TXT, independent of checkboxes. For a game archive copy, check only desired resources and use Save selected copy…." }, "Es werden ganze Ressourcen ersetzt. Hinzugefügte oder entfernte Pfade werden nicht automatisch zusammengeführt.", "Whole resources are replaced. Added or removed paths are not merged automatically."),
                T("Dateien & Zuordnung", "Files & destinations", "Die wichtigsten Archive auf einen Blick.", "Key archives at a glance.", L.T("Custom Pack", "Custom pack"), new[] { "Menüs|Title.szs: Titel/Lizenz. MenuSingle.szs: Einzelspieler. MenuMulti.szs: Multiplayer.", "Globus & Hintergrund|Globe.szs: Online-Menüs. Earth.szs: Globusszene/Himmel. globe.arc: Globusfarben. BackModel.szs: Menümodelle.", "HUD & Schrift|Race.szs und Sprachvariante: HUD. RaceAssets.szs: zusätzliche RR-Elemente. Font.szs: allgemeine Schriften. ReplacedAssets.szs: zusätzliche Zahlen-/Slash-Ressourcen." }, new[] { "Menus|Title.szs: title/license. MenuSingle.szs: single player. MenuMulti.szs: multiplayer.", "Globe and background|Globe.szs: online menus. Earth.szs: globe scene/sky. globe.arc: globe colours. BackModel.szs: menu models.", "HUD and fonts|Race.szs and language variant: HUD. RaceAssets.szs: extra RR elements. Font.szs: general fonts. ReplacedAssets.szs: additional digit/slash resources." }, "Nur benötigte Dateien übernehmen und die ursprünglichen Dateinamen beibehalten.", "Install only needed files and retain their original filenames."),
                T("RR-MKWii Game HUD Tool & Positionen", "RR-MKWii Game HUD Tool & positions", "Menüelemente und Race-HUD-Layouts visuell bearbeiten.", "Visually edit menu elements and race HUD layouts.", L.T("Tools → RR-MKWii Game HUD Tool  /  RR-MKWii Race HUD Tool → HUD visuell verschieben", "Tools → RR-MKWii Game HUD Tool  /  RR-MKWii Race HUD Tool → Move HUD visually"), new[] { "Archiv und Layout wählen|MenuSingle.szs, MenuMulti.szs oder Title.szs öffnen. Die Layoutsuche filtert Dateinamen, etwa button oder select. Geteilte Texturen über Archiv hinzufügen laden.", "Visuell bearbeiten|Element anklicken und ziehen. Ganzes Layout verschieben aktivieren, um alle Kinder gemeinsam zu bewegen. Im Race HUD ist dies voreingestellt. Acht Ziehpunkte ändern die Größe; Umschalt hält die Proportionen. Bei Gruppen werden alle Kinder skaliert. Bildformat (16:9 oder 4:3) und Spieleransicht wählen. Verfügbare BRCTR-Positionen werden automatisch geladen. Der Bildschirmrahmen zeigt die zugehörige Bildschirmreferenz. Ohne BRCTR bleibt die Vorschau lokal. Die Renderauflösung des Spiels bleibt unverändert. Rechts Position, Skalierung, Drehung und Deckkraft einstellen. Mausrad zoomt; mit gedrückter Mausradtaste die Ansicht verschieben. Einpassen setzt Zoom und Ansicht zurück.", "Farben und Bilder|Elementfarbe färbt ein einzelnes Bild-/Textelement. Texturfarben ändert Grund- und Konturfarbe. Texturersatz betrifft alle Verwendungen derselben Texturdatei. Ein Referenzbild dient nur als Hintergrundhilfe.", "Übernehmen und testen|Rückgängig/Wiederholen ist verfügbar. Unten Archivkopien speichern. Im Race HUD zuerst übernehmen, anschließend dort die bearbeiteten Archive speichern und im Testing-Pack prüfen." }, new[] { "Choose archive and layout|Open MenuSingle.szs, MenuMulti.szs or Title.szs. Search filters layout filenames, e.g. button or select. Add archives to resolve shared textures.", "Edit visually|Click and drag an element. Enable Move whole layout to move all children together; this is the default in Race HUD. Use the eight handles to resize; hold Shift to keep proportions. Groups scale all children. Choose aspect ratio (16:9 or 4:3) and player view. Available BRCTR placements load automatically. The frame shows the corresponding screen reference; without BRCTR, the preview stays local. Game render resolution is unchanged. Adjust position, scale, rotation and opacity on the right. Mouse wheel zooms; hold the middle mouse button to pan the view. Fit view resets zoom and pan.", "Colours and images|Element tint colours a picture/text element. Texture colours edits base and outline colours. Replacing a texture affects all uses of the same file. Reference images are visual guides only.", "Apply and test|Undo/Redo is available. Save archive copies at the bottom. In Race HUD, apply first, then save the edited archives there and test your copies in your testing pack." }, "Die Vorschau zeigt ein statisches Teillayout, keinen vollständigen Spielbildschirm. Animationsziele sind markiert; Animationen und Spielcode können Änderungen überschreiben. Texte, 3D-Modelle und Materialeffekte sind nicht spielgetreu.", "The preview shows one static component layout, not a complete game screen. Animation targets are marked; animations and game code may override changes. Text, 3D models and material effects are not game-accurate."),
                T("Rückgängig & Sicherungen", "Undo & backups", "Bearbeitungsschritte zurücknehmen oder eine Sicherung wiederherstellen.", "Undo edits or restore a backup.", L.T("Rückgängig  /  Original  /  Sicherung", "Undo  /  Original  /  Backup"), new[] { "Letzten Schritt zurücknehmen|Rückgängig nimmt den letzten Bearbeitungsschritt zurück; Wiederholen stellt ihn wieder her. Ein Sammelimport wird als ganzer Schritt zurückgenommen.", "Originaloptionen|Originalfarben oder Originalmuster gelten für den nächsten Build aus der geöffneten Quelle.", "Nach dem Export|Bereits geschriebene Dateien mit deiner Sicherung wiederherstellen." }, new[] { "Undo the last step|Undo reverses the last edit; Redo restores it. A batch import is undone as one complete step.", "Original options|Original colours/pattern apply to the next build from the opened source.", "After export|Restore already written files from your backup." }, "Auswahl leeren setzt keine bereits exportierte Datei zurück.", "Clearing a selection does not revert an already exported file."),
                T("Prüfen & Vorschaugrenzen", "Checks & preview limits", "Was die Vorschau bestätigt – und was erst das Spiel zeigt.", "What a preview confirms, and what requires the game.", L.T("Vorschau  →  Separate Kopie  →  Im Spiel testen", "Preview  →  Separate copy  →  In-game test"), new[] { "Bild und Text|Texturvorschauen zeigen dekodierte Bilder. Textproben ersetzen nicht das tatsächliche Menü-Layout.", "Animation und 3D|Schematische Ansichten sind gekennzeichnet. GIF-Unterstützung hängt vom Zielbereich ab; Globus-GIFs werden als Standbild verwendet.", "Streckendaten|KMP/KCL über die Streckenprüfung validieren. Dafür muss Wiimms Toolchain verfügbar sein." }, new[] { "Images and text|Texture previews show decoded artwork. Text samples do not simulate the actual menu layout.", "Animation and 3D|Schematic views are labelled. GIF support depends on the target; globe GIFs use a still frame.", "Track data|Validate KMP/KCL using the track check. Wiimms tools must be available." }, "Zum Abschluss im separaten Testing-Pack prüfen. Teamfarben und Animationen können das Ergebnis beeinflussen.", "Finish by testing in a separate pack. Team colours and animations may affect the result."),
                T("Programm aktualisieren", "Update Studio", "Neue Versionen prüfen und installieren.", "Check for and install new versions.", L.T("Navigation → Hilfe → Nach Updates suchen", "Navigation → Help → Check for updates"), new[] { "Automatisch prüfen|Beim Programmstart wird im Hintergrund nach Updates gesucht. Nur eine neuere verfügbare Version öffnet ein Fenster. Ohne Internet kannst du normal weiterarbeiten.", "Update installieren|Jetzt aktualisieren lädt den Installer herunter und prüft seine Prüfsumme. Speichere deine Änderungen und schließe Studio. Im Update-Fenster Installieren und neu starten wählen.", "Später fortfahren|Später schließt den Hinweis. Links in der Hilfe kannst du mit Nach Updates suchen jederzeit erneut prüfen." }, new[] { "Automatic check|Studio checks in the background at startup. Only a newer available version opens a window. You can keep working offline.", "Install an update|Update now downloads the installer and checks its checksum. Save your work and close Studio. In the update installer, choose Install and restart.", "Update later|Later dismisses the notification. You can check again with Check for updates in the help sidebar." }, "Projekte, Einstellungen und optionale Tools bleiben erhalten. Die erste öffentliche Beta benötigt einmalig den neuen Installer-Download.", "Projects, settings and optional tools are kept. The first public beta needs a one-time download of the new installer."),
                T("Links & Dokumentation", "Links & documentation", "Referenzen und zusätzliche Programme.", "References and specialist programs.", L.T("Hilfe / Toolchain", "Help / Toolchain"), new[] { "Dokumentation & Credits|Die Projektseite unten enthält Anleitung und Downloads. Links in der Hilfe öffnet Über Studio die Credits und Lizenzen.", "Zusätzliche Programme|Navigation → Programme zeigt Zweck, Installationsstatus und Pfad der Backends." }, new[] { "Documentation & credits|The project page below provides instructions and downloads. Choose About Studio in the help sidebar for Credits and licenses.", "Additional programs|Navigation → Tools & settings shows each backend's purpose, installation status and path." }, "Die folgenden Links öffnen deinen Browser.", "The links below open your browser.")
            };
            topics[topics.Count - 1].IncludeLinks = true;
            topics.Insert(0, T("Navigation & Tastatur", "Navigation & keyboard", "Werkzeuge bleiben als Arbeitsflächen im Hauptfenster geöffnet.", "Tools stay open as workspaces in the main window.", L.T("Navigation links → Arbeitsfläche → Aktionen", "Left navigation → Workspace → Actions"),
                new[] { "Arbeitsfläche wählen|Links Archiv, Pack Maker oder einen Gestaltungsbereich wählen. Beim Wechsel bleibt der Editorstand erhalten. Umfangreiche Auswahl- und Übernahmefenster öffnen separat.", "Symbole lesen|Ordner: öffnen; Diskette: speichern; Pfeil aus dem Rahmen: exportieren; Pfeil in den Rahmen: importieren. Gebogene Pfeile: Rückgängig/Wiederholen; Lupe: suchen; gegenläufige Pfeile: einpassen. Mit der Maus verweilen oder per Tab fokussieren, um die Erklärung zu lesen.", "Tastatur nutzen|Tab/Umschalt+Tab bewegt den Fokus; Enter aktiviert die fokussierte Aktion; Escape bricht Dialoge ab. Strg+Z macht rückgängig, Strg+Y oder Strg+Umschalt+Z wiederholt, soweit der Editor diese Aktionen anbietet.", "Im Archiv arbeiten|Strg+O öffnet; Strg+S speichert; Strg+Umschalt+S speichert unter; Strg+F sucht; Strg+Enter bearbeitet die ausgewählte Ressource. Diese Befehle gehören zur Archiv-Arbeitsfläche. F1 öffnet die Hilfe; hier sucht Strg+F nach Themen." },
                new[] { "Choose a workspace|Select Archive, Pack Maker or a creative area on the left. Switching keeps the editor session. Large selection and confirmation windows open separately.", "Read the icons|Folder: open; disk: save; arrow leaving a frame: export; arrow entering a frame: import. Curved arrows: Undo/Redo; magnifier: search; opposing arrows: fit view. Hover or focus with Tab to read the explanation.", "Use the keyboard|Tab/Shift+Tab moves focus; Enter activates the focused action; Escape cancels dialogs. Ctrl+Z undoes; Ctrl+Y or Ctrl+Shift+Z redoes where supported by the editor.", "Work in Archive|Ctrl+O opens; Ctrl+S saves; Ctrl+Shift+S saves as; Ctrl+F searches; Ctrl+Enter edits the selected resource. These commands belong to the Archive workspace. F1 opens help; Ctrl+F searches topics here." },
                "Die Bedeutung einer Aktion steht im Tooltip und im zugänglichen Namen. Nicht jede Ressource ist direkt bearbeitbar; der Inspector erklärt erkannte Formate.",
                "Actions have tooltips and accessible names. Some resources cannot be edited directly; the Inspector explains recognised formats."));
            topics.Insert(0, T("Charaktere & Modellprojekte", "Characters & model projects", "Ersatzziel, Modellgestaltung und Spielausgabe getrennt prüfen.", "Review the replacement target, model design and game output separately.", L.T("Navigation → Charakter", "Navigation → Character"),
                new[] { "Ziel und Quelle wählen|Gültiges Pack und passende RR-Quellen laden. Basischarakter und ersetzte Variante prüfen. Eigenes Modell öffnen oder ein gespeichertes .murcharacter über Projekt öffnen laden.", "Fertige Spieldateien|Spieldateien wählen… öffnet fertige BRRES/SZS-Dateien. Dateien prüfen zeigt Fehlendes; Fehlendes ergänzen… führt zur passenden Ergänzung. Für den Wechsel zu einem eigenen 3D-Modell zuerst das Projekt speichern und einen neuen Charakterersatz beginnen.", "Namen und Bilder|Namen importieren… lädt vorhandene Namen; Archiv hinzufügen… lädt die passenden Namensarchive. Textvorschau… kontrolliert die Beschriftung. Minimap und Fahrzeuglogo haben getrennte Bildziele.", "Skalierte Modellkopie|Skalierte Kopie speichern… gibt eine separate Kopie des eigenen 3D-Modells aus. Projekt speichern erhält den Arbeitsstand; Charakter exportieren erstellt die Spieldateien.", "Gestalten und bewegen|Name, Minimap-Symbol und Fahrzeug-Emblem getrennt bearbeiten. Menü und Fahren besitzen eigene Haltung und Größe. Links/rechts gilt aus Sicht der Figur. Gelenke und unerreichbare Fahrzeugkontakte prüfen und bei Bedarf korrigieren.", "Referenz festlegen|Die RR-Variante oder eine menschliche Bewegungsvorlage ausdrücklich auswählen. Sie dient der Bewegung; der Ersatzziel-Slot bleibt gleich. Zusatzteile nur bei Bedarf einschalten.", "Projekt oder Export wählen|Projekt speichern erhält den bearbeitbaren Stand. Namen-only exportiert Namen. Vollständiger Charakterexport erzeugt die flachen Spieldateien in MUR_EDITED/Character replacement files; deren Inhalt gehört nach Sicherung in den Pack-Hauptordner. Referenzmodelle werden nicht exportiert." },
                new[] { "Choose the target and source|Load a valid pack and matching RR sources. Check the base character and replacement variant. Open your own model or use Open project for a saved .murcharacter.", "Ready-made game files|Choose game files… opens ready-made BRRES/SZS files. Check files lists missing items; Complete missing items… leads to the relevant action. To switch to your own 3D model, save the project and start a new character replacement first.", "Names and images|Import names… loads existing names; Add archive… loads matching name archives. Preview text… checks labels. Minimap and vehicle emblems have separate image targets.", "Scaled model copy|Save scaled copy… exports a separate copy of your own 3D model. Save project keeps the editable work; Export character creates the game files.", "Design and pose|Edit the name, minimap icon and vehicle emblem separately. Menu and driving have separate poses and sizes. Left/right is from the character's perspective. Review joints and unreachable vehicle contacts and correct them as needed.", "Choose a reference|Explicitly choose the RR variant or a human motion template. It provides motion without changing the replacement slot. Enable extra parts only as needed.", "Choose project or export|Save project keeps the editable state. Names-only exports names. Full character export creates flat game files in MUR_EDITED/Character replacement files; back up your pack and copy the contents to its root folder. Reference models are not exported." },
                "GLB, glTF, BLEND, USDZ, DAE und OBJ sind dokumentierte Modellformate; nicht jede Variante ist vollständig geprüft. Vorschau, erfolgreicher Export und FPS im Spiel sind getrennte Prüfungen. Manuelle Korrektur bestätigt keine gelöste automatische Sonderposenerkennung.",
                "GLB, glTF, BLEND, USDZ, DAE and OBJ are documented model formats; not every variant is fully tested. Preview, successful export and in-game FPS are separate checks. Manual correction does not prove automatic special-pose detection is solved."));
            topics.Insert(0, T("Custom Pack vorbereiten", "Prepare a custom pack", "RR-Dateien als geschützte Quelle für deine Bearbeitung verwenden.", "Use RR files as protected sources for your editing work.", L.T("Navigation → Pack Maker", "Navigation → Pack Maker"),
                new[] { "RR und Region wählen|RR-Installation öffnen und PAL, USA oder Japan festlegen. Der Pack Maker benötigt selbst kein ausgewähltes Pack.", "Fehlendes ergänzen|Vorhandene RR-Dateien verwenden. ISO/WBFS ist nur zum Ergänzen fehlender Earth.szs, BackModel.szs und globe.arc vorgesehen; passende fehlende Dateien auswählen.", "Pack erstellen|Neuen Ausgabeordner wählen und Kopien erstellen. Title_U.szs, Race_U.szs und Common_U.szs werden gemäß Region als _E, _U oder _J kopiert; die Quelle bleibt unverändert.", "Editor starten|Das Pack in der gewünschten Arbeitsfläche auswählen und passende Quelldateien erfolgreich laden. Erst dann werden die benötigten Bearbeitungsaktionen verfügbar." },
                new[] { "Choose RR and region|Open the RR installation and select PAL, USA or Japan. Pack Maker itself does not require a selected pack.", "Supply missing files|Use existing RR files first. ISO/WBFS is intended only to supply missing Earth.szs, BackModel.szs and globe.arc; choose the matching missing files.", "Create the pack|Choose a new output folder and create copies. Title_U.szs, Race_U.szs and Common_U.szs are copied as _E, _U or _J according to region; sources remain unchanged.", "Start an editor|Choose the pack in the desired workspace and successfully load matching source files. The required editing actions become available afterwards." },
                "Pack-Auswahl allein lädt keine Quelle. Abbruch einer Dateiauswahl aktiviert nichts. Sprachbeispiele E/U/J sperren keine anderen unterstützten Sprachdateien.",
                "Choosing a pack does not load a source. Cancelling file selection enables nothing. E/U/J language examples do not restrict other supported language files."));
            topics.Add(T("Archive & einzelne Dateien", "Archives & individual files", "Dateien finden, bearbeiten und als eigene Kopie speichern.", "Find, edit and save files as a separate copy.", L.T("Navigation → Archiv", "Navigation → Archive"),
                new[] { "Öffnen|SZS/U8/ARC öffnen und einen Eintrag im Baum wählen. Vorschau und Details zeigen den Inhalt. Einzelne BRLAN-, BRLYT-, TPL- und TEX0-Ressourcen können separat geöffnet werden.", "Bearbeiten|Importieren fügt Dateien hinzu; Ersetzen tauscht die ausgewählte Datei aus. Texturimport zeigt das Ergebnis vor der Übernahme. Rückgängig/Wiederholen prüfen. Für Animationen eine BRLAN wählen und unter Werkzeuge → Weitere Werkzeuge → Ausgewählte BRLAN bearbeiten / GIF öffnen; dort erklärt Hilfe die Animation und den GIF-Import. Streckenarchive unter Werkzeuge → Weitere Werkzeuge → Streckendateien prüfen… kontrollieren.", "Ausgabe wählen|Eintrag exportieren schreibt nur die ausgewählte Ressource. Speichern unter schreibt eine Archivkopie. Speichern überschreibt die geöffnete Datei. Zum Schutz des Originals zuerst Speichern unter verwenden." },
                new[] { "Open|Open SZS/U8/ARC and select a tree entry. Preview and details show its contents. Individual BRLAN, BRLYT, TPL and TEX0 resources can be opened separately.", "Edit|Import adds files; Replace replaces the selected file. Texture import previews the result before applying it. Check Undo/Redo. For animation, select a BRLAN and use Tools → More tools → Edit selected BRLAN / GIF; its Help explains animation and GIF import. Check course archives with Tools → More tools → Check race-track files….", "Choose the output|Export entry writes only the selected resource. Save as writes an archive copy. Save overwrites the opened file. To preserve the original, use Save as first." },
                "Eine BRLAN enthält Animationsdaten, keine Bildpixel. Zugehörige BRLYT/TPL-Ressourcen und ihre Verweise müssen im passenden Archiv vorhanden sein.",
                "BRLAN contains animation data, not picture pixels. Related BRLYT/TPL resources and their references must be present in the matching archive."));
            topics.Add(T("Menübilder & Texturen", "Menu images & textures", "Eine vorhandene Textur gezielt durch eigenes Artwork ersetzen.", "Replace an existing texture with your own artwork.", L.T("Navigation → Menübilder", "Navigation → Menu images"),
                new[] { "Quelle laden|Passendes Menüarchiv öffnen und eine Textur auswählen; TPL/TEX0 können auch direkt geöffnet werden.", "Einzelbild einsetzen|Eigenes Bild laden, Zuschnitt und Alpha prüfen. Bei TPL Ziel-Format und Mipmaps wählen; Original ist voreingestellt. Unterstützte Formate: I4, I8, IA4, IA8, RGB565, RGB5A3, RGBA32, CI4, CI8 und CMPR. Nach Import / Komprimierung zeigt das tatsächlich kodierte Bild. Bild übernehmen ändert die Arbeitskopie; Abbrechen verwirft den Import.", "Transparenz prüfen|Vorschaukanal im Einzeltexturfenster oder TPL-Einzelimport wählen: RGBA zeigt das normale Bild, RGB blendet Transparenz aus, Alpha zeigt die Deckkraft als Graustufen. Im Import wechseln beide Bilder gemeinsam. Nur die Ansicht ändert sich; Import, Speichern und PNG-Export behalten die echten Bilddaten.", "Texturen gesammelt bearbeiten|Texturen gesammelt… öffnen und PNGs exportieren… wählen. Eindeutige Bildpfade der Sammlung beibehalten. Nach der Bildbearbeitung Bildordner wählen… und Importvorschau erstellen. Zeilen, Fehler und kodierte Bilder prüfen, dann Änderungen gemeinsam übernehmen. Rückgängig stellt den gesamten vorherigen Arbeitsstand wieder her.", "Kopie speichern|Die bearbeitete Textur oder das Archiv separat speichern. Das Originalformat und die Bildverwendungen im Menü anschließend prüfen." },
                new[] { "Load the source|Open a matching menu archive and choose a texture; TPL/TEX0 can also be opened directly.", "Insert one image|Load artwork and review fitting and alpha. For TPL, choose the target format and mipmaps; Original is the default. Supported formats: I4, I8, IA4, IA8, RGB565, RGB5A3, RGBA32, CI4, CI8 and CMPR. After import / compression shows the actually encoded image. Apply image changes the working copy; Cancel discards the import.", "Inspect transparency|Choose Preview channel in the standalone texture window or TPL single-image import: RGBA shows the normal image, RGB ignores transparency, Alpha shows opacity in grayscale. Both import images switch together. Only the view changes; import, saving and PNG export keep the actual image data.", "Edit batch textures|Open Batch textures… and choose Export PNGs…. Keep the collection’s unique image paths. After editing artwork, Choose image folder… and Prepare import preview. Review rows, errors and encoded images, then Apply changes together. Undo restores the whole previous edit state.", "Save a copy|Save the edited texture or archive separately. Then check the original format and how the menu uses the image." },
                "Sammelimport erhält Format und Mipmapumfang; freie TPL-Formatwahl gilt für den Einzelimport. TEX0/BRRES haben andere Bearbeitungswege. Gemeinsam verwendete Texturen ändern mehrere Elemente. Materialien, Teamfarben und Animationen können die Darstellung im Spiel verändern.",
                "Batch import preserves format and mipmap count; free TPL format selection applies to single-image import. TEX0/BRRES use different editing routes. Shared textures affect multiple elements. Materials, team colours and animations can change their in-game appearance."));
            var quick = topics.Find(t => t.Title == L.T("Schnellstart", "Quick start"));
            topics.Remove(quick);
            topics.Insert(0, quick);
            Bind(topics, "Custom Pack vorbereiten", "Prepare a custom pack", "pack", "Pack Maker", "Pack Maker");
            Bind(topics, "Charaktere & Modellprojekte", "Characters & model projects", "character", "Charakter", "Character");
            Bind(topics, "Archive & einzelne Dateien", "Archives & individual files", "archive", "Archiv", "Archive");
            Bind(topics, "Menübilder & Texturen", "Menu images & textures", "textures", "Menübilder", "Menu images");
            Bind(topics, "RR-Effektfarben", "RR effect colours", "effects", "Effekte", "Effects");
            Bind(topics, "Pack-Werkstatt", "Pack Workshop", "workshop", "Pack-Werkstatt", "Pack workshop");
            Bind(topics, "Änderungen kombinieren", "Combine edits", "merge", "Zusammenführen", "Merge changes");
            Bind(topics, "Menühintergründe", "Menu backgrounds", "background", "Hintergründe", "Backgrounds");
            Bind(topics, "Globus, Himmel & Modelle", "Globe, sky & models", "background", "Hintergründe → Weitere UI", "Backgrounds → Other UI");
            Bind(topics, "Race HUD: Bilder & Zahlen", "Race HUD: pictures & numbers", "hud", "Rennanzeigen", "Race HUD");
            Bind(topics, "Minimap-Farben", "Minimap colours", "hud", "Rennanzeigen → Kartenfarben", "Race HUD → Map colours");
            Bind(topics, "Input Viewer", "Input Viewer", "hud", "Rennanzeigen → Input Viewer", "Race HUD → Input Viewer");
            Bind(topics, "Schriften ändern", "Change fonts", "font", "Schriften", "Fonts");
            Bind(topics, "Menütexte", "Menu texts", "text", "Spieltexte", "Game text");
            Bind(topics, "Musik & Loops", "Music & loops", "audio", "Musik & Loops", "Music & loops");
            Bind(topics, "Theme-Projekte", "Theme projects", "theme", "Theme Project", "Theme Project");
            Bind(topics, "Archive vergleichen", "Compare archives", "compare", "Vergleichen", "Compare archives");
            Bind(topics, "RR-MKWii Game HUD Tool & Positionen", "RR-MKWii Game HUD Tool & positions", "menu", "Menü-Layout / Rennanzeigen → HUD visuell verschieben", "Menu layout / Race HUD → Move HUD visually");
            Bind(topics, "Links & Dokumentation", "Links & documentation", "settings", "Programme / Hilfe → Über Studio", "Tools & settings / Help → About Studio");
            topics.Find(t => t.Title == L.T("Programm aktualisieren", "Update Studio")).ChecksUpdates = true;
            Visual(topics);
            Examples(topics);
            return topics;
        }

        private static void Examples(List<HelpTopic> topics)
        {
            E(topics, "Schnellstart", "Quick start", "Eine violette Menüleiste", "A purple menu bar",
                "MenuSingle.szs in einer Packkopie öffnen.|Unter Menübilder die obere Leiste wählen und Farben öffnen.|Violett anwenden, Archivkopien speichern und das Einzelspielermenü neu starten.",
                "Open MenuSingle.szs from a pack copy.|In Menu images, choose Top bar and open Colours.|Apply purple, save archive copies and restart the single-player menu.",
                "Eine Archivkopie mit der neuen Leistenfarbe; die Quelle bleibt erhalten.", "An archive copy with the new bar colour; the source is preserved.");
            E(topics, "Custom Pack vorbereiten", "Prepare a custom pack", "Ein PAL-Testpack anlegen", "Create a PAL test pack",
                "Im Pack Maker RR auswählen und als Region PAL wählen.|Fehlende Globusdateien nur bei Bedarf aus deiner ISO/WBFS ergänzen.|Einen neuen Ausgabeordner mit dem Namen Mein Testpack wählen und das Pack erstellen.",
                "In Pack Maker, choose RR and select PAL.|Supply missing globe files from your ISO/WBFS only if needed.|Choose a new output folder named My test pack and create the pack.",
                "Die regionalen Title_U/Race_U/Common_U-Kopien heißen _E. Danach im Editor das Pack und seine Quelle laden.", "The regional Title_U/Race_U/Common_U copies use _E. Then load the pack and its source in an editor.",
                new HelpPicture("pack", "Pack Maker: Zuerst RR-Quelle und Region wählen; Weiter bleibt bis dahin gesperrt.", "Pack Maker: Choose the RR source and region first; Next remains disabled until then."));
            E(topics, "Charaktere & Modellprojekte", "Characters & model projects", "Eine eigene Figur statt einer RR-Variante", "Use your own character in an RR slot",
                "Charakter ersetzen wählen und die gewünschte vorhandene RR-Variante bestätigen. Das Ersatzziel oben kontrollieren.|Eigenes 3D-Modell wählen und eine GLB-Datei öffnen. In Haltung & Bewegung Menü und Fahren, Gelenke und Lenkerkontakte prüfen.|Projekt speichern schreibt eine .murcharacter für spätere Korrekturen. Anschließend in Prüfen & Export Charakter exportieren wählen.|Alle flachen Dateien aus MUR_EDITED/Character replacement files in die gesicherte Packkopie übernehmen; Pack-Dateien abgleichen und das Pack neu starten.",
                "Choose Replace character and confirm the installed RR variant. Check the replacement target at the top.|Choose Own 3D model and open a GLB file. In Pose & movement, review menu and driving poses, joints and handlebar contacts.|Save project creates a .murcharacter for later edits. Then choose Export character in Check & export.|Copy all flat files from MUR_EDITED/Character replacement files into your backed-up pack copy; compare pack files and restart the pack.",
                "Projekt und Spieldateien sind getrennte Ergebnisse. Eine Bewegungsreferenz ändert den Ersatzziel-Slot nicht; GLB ist ein Beispiel, keine Zusage für jedes Modell.", "The project and game files are separate outputs. A movement reference does not change the replacement slot; GLB is an example, not a guarantee for every model.",
                new HelpPicture("character", "Nach der echten RR-Zielauswahl: 3D-Modell oder fertige Spieldateien wählen. Namen, Minimap und Emblem sind eigene Bereiche.", "After selecting the actual RR target: choose a 3D model or ready-made game files. Names, minimap and emblem have separate areas."));
            E(topics, "Schriften ändern", "Change fonts", "Eine neue Hauptschrift für Menü und Renntext", "A new main font for menus and race text",
                "Font.szs laden. Schriften wählen… öffnet die Auswahl für Latein und Zahlen, Japanisch und weitere Alphabete.|In Latein und Zahlen TTF wählen… anklicken, z. B. eine geeignete Arial-TTF wählen und als Hauptschrift belassen. Japanisch nur mit einer passenden zusätzlichen TTF belegen.|Schriften übernehmen wählen. Die Textprobe Mario Kart Wii 0123456789 ÄÖÜ prüfen; Füllung und Kontur bei Bedarf einstellen.|Den gewünschten Umfang prüfen. Für koordinierte HUD-Zahlen passende Race.szs und ReplacedAssets.szs sowie angebotene Begleiter laden. Alle angezeigten bearbeiteten Kopien zusammen exportieren.",
                "Load Font.szs. Choose fonts… opens the selection for Latin and numbers, Japanese and more alphabets.|Click Choose TTF… for Latin and numbers, choose a suitable Arial TTF for example and keep it as Main. Assign Japanese only with a suitable additional TTF.|Choose Use these fonts. Inspect the Mario Kart Wii 0123456789 ÄÖÜ sample; adjust fill and outline if needed.|Check the desired scope. For coordinated HUD digits, load matching Race.szs and ReplacedAssets.szs and offered companions. Export all displayed edited copies together.",
                "Eine Hauptschrift genügt. Nicht enthaltene Zeichen behalten das Original; zusätzliche Schriftsysteme sind optional. Sterne, Pokale und Positionssymbole separat prüfen.", "One main font is enough. Missing characters keep their original appearance; extra writing systems are optional. Review stars, trophies and position symbols separately.",
                new HelpPicture("fonts", "Nach Font.szs laden: Schriften wählen… ist der nächste Schritt. Textprobe und Umfang stehen im selben Werkzeug.", "After loading Font.szs: Choose fonts… is the next step. The sample and scope are in the same tool."),
                new HelpPicture("font-selection", "Die echte Schriftauswahl: Jede Zeile kann Hauptschrift sein. Weitere TTF-Dateien sind freiwillig.", "The actual font selector: Any row can be Main. Additional TTF files are optional."));
            E(topics, "Menübilder & Texturen", "Menu images & textures", "Ein breites Bild in eine Menütextur einpassen", "Fit a wide picture into a menu texture",
                "MenuSingle.szs laden, eine passende Textur wählen und Bild ersetzen… öffnen.|Eigenes PNG wählen. Einpassen erhält das Seitenverhältnis; Füllen schneidet Ränder ab; Strecken verändert die Proportionen.|Ziel-Format und Mipmaps für TPL prüfen; Original ist voreingestellt. Original und Nach Import / Komprimierung vergleichen, besonders transparente Ränder. Bild übernehmen wählen und Archivkopien speichern. Für mehrere Bilder stattdessen Texturen gesammelt… öffnen, PNGs exportieren…, Bildpfade beibehalten und später über Bildordner wählen… die Importvorschau erstellen. Zeilen prüfen, Änderungen gemeinsam übernehmen und Archivkopien speichern.",
                "Load MenuSingle.szs, select the texture and open Replace picture….|Choose your PNG. Fit preserves its aspect ratio; Fill crops edges; Stretch changes proportions.|Review the TPL target format and mipmaps; Original is the default. Compare Original and After import / encoding, especially transparent edges. Choose Apply image and save archive copies. For multiple images, use Batch textures…, Export PNGs…, retain image paths, then Choose image folder… and Prepare import preview. Review rows, Apply changes together and save archive copies.",
                "Die Vorschau zeigt die tatsächlich kodierten Farben. Gemeinsam verwendete Texturen ändern alle ihre Verwendungen.", "The preview shows the actually encoded colours. Shared textures change everywhere they are used.",
                new HelpPicture("image-import", "Echter Importdialog mit eigenem Beispielbild: links Zieltextur, rechts Ergebnis nach Einpassen und Kodierung.", "Actual import dialog with original example artwork: target texture on the left, result after fitting and encoding on the right."));
