        private static void H(List<HelpTopic> topics, string de, string en, string headingsDe, string headingsEn, params StudioIcon[] icons)
        {
            var topic = topics.Find(t => t.Title == L.T(de, en));
            topic.ExampleHeadings = L.T(headingsDe, headingsEn).Split('|');
            topic.ExampleIcons = icons.Length > 0 ? icons : new[] { StudioIcon.Open, StudioIcon.Settings, StudioIcon.Export };
        }

        private static void E(List<HelpTopic> topics, string de, string en, string titleDe, string titleEn,
            string stepsDe, string stepsEn, string resultDe, string resultEn, params HelpPicture[] pictures)
        {
            var topic = topics.Find(t => t.Title == L.T(de, en));
            topic.ExampleTitle = L.T(titleDe, titleEn);
            topic.ExampleSteps = L.T(stepsDe, stepsEn).Split('|');
            topic.ExampleResult = L.T(resultDe, resultEn);
            topic.Pictures = pictures;
        }

