        private static void V(List<HelpTopic> topics, string de, string en, StudioIcon icon, string group,
            string[] stepsDe, string[] stepsEn, string noteDe, string noteEn, StudioIcon[] icons = null)
        {
            var topic = topics.Find(t => t.Title == L.T(de, en));
            topic.Icon = icon;
            topic.Group = group;
            topic.VisualSteps = L.IsGerman ? stepsDe : stepsEn;
            topic.VisualNote = L.T(noteDe, noteEn);
            topic.StepIcons = icons ?? (topic.VisualSteps.Length == 4
                ? new[] { StudioIcon.Open, StudioIcon.Settings, StudioIcon.Check, StudioIcon.Export }
                : new[] { StudioIcon.Open, StudioIcon.Settings, StudioIcon.Export });
        }

        private static void Bind(List<HelpTopic> topics, string de, string en, string key, string routeDe, string routeEn)
        {
            var topic = topics.Find(t => t.Title == L.T(de, en));
            topic.WorkspaceKey = key;
            topic.Route = L.T("Navigation → ", "Navigation → ") + L.T(routeDe, routeEn);
        }
    }
